\;\land\;
\bigl(\forall a,b \in S,\; a < b \Rightarrow \neg(b < a)\bigr)
\;\land\;
\bigl(\forall a,b,c \in S,\; a < b \land b < c \Rightarrow a < c\bigr).
\]

